import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"香港浸会大学附属学校王锦辉中小学 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-810a178f","school_zh":"香港浸会大学附属学校王锦辉中小学","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"香港浸会大学附属学校王锦辉中小学 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-WKF-FIRST","C2223-WKF-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-810a178f/s1/2022-23-interview.md","filePath":"reports/school-810a178f/s1/2022-23-interview.md"}'),p={name:"reports/school-810a178f/s1/2022-23-interview.md"};function n(a,o,c,l,g,i){return t(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="香港浸会大学附属学校王锦辉中小学-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">香港浸会大学附属学校王锦辉中小学 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#香港浸会大学附属学校王锦辉中小学-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;香港浸会大学附属学校王锦辉中小学 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-810a178f">← 返回香港浸会大学附属学校王锦辉中小学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-wkf-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-wkf-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-wkf-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>先笔头准备，再分科解释</strong></p><p>多份反馈先用约20分钟阅读或完成中文、英文、数学及常识／社会议题四部分，再到另一课室，依次向四位老师口述答案。可能四人一组入场，但各科是一对一回答。部分先观看影片；有八页题卷的版本。</p><p><strong>草稿使用差异</strong></p><p>有版本可在白纸自由记笔记，够钟后收走，再凭记忆回答；另有学生在中文问答时可看自己的作答。各场指引不同，不能统一假设可带笔记进入面谈。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话；部分回答可选粤语</p><p><strong>阅读与概括</strong></p><p>文章主题包括以蚕自喻、丁香花；用一句话概括主旨，解释修辞，如拟人，或解释诗句。部分以普通话读文章、指定句子或划线词语，再回答问题。</p><p><strong>词语与填空</strong></p><p>三个成语选一个解释，如“掩耳盗铃”，另有“狐假虎威”；约三道不供词填空。也有中文情境题。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读及阅读问答</strong></p><p>文章主题包括校规；题型涵盖供词填空、文章主旨、内容问答，部分另加两道延伸题。朗读有约四分之三张A4纸长的版本，限时结束即停止，有学生未读完。</p><p><strong>观点延伸</strong></p><p>比较网课与面授；按文章内容谈是否到外国读书等。</p></blockquote><blockquote><p><strong>数学：</strong> 中文为一份反馈明确；其余未注明</p><p><strong>计算与即时心算</strong></p><p>题量有3、4、8或10题等不同版本，涉及小学六年级知识、分数乘法、异分母分数加减及奥数式题目。部分要求限时心算并口述十道题，以加减为主；也有老师另加一道即时四则运算。</p><p><strong>条件推理与规律</strong></p><p>按条件将星、圆、三角放入三个位置；类似Mastermind的猜密码游戏；图形从一个点变为五个点，继续推断变化规律。</p></blockquote><blockquote><p><strong>常识与社会议题：</strong> 语言未注明</p><p><strong>懒惰与社会发展</strong></p><p>讨论懒惰对个人及世界发展的好处和坏处。一个版本提供名人观点作参考，大意为懒惰的人可能更开心、压力较少，学生须提出自己的看法。</p><p><strong>环保与公共设施</strong></p><p>谈环保计划、环保物料的用法及优点；说出市民不进行垃圾分类的两个原因。关爱座题要求各说两个好处和坏处。另有约两分钟讨论麦当劳无饮管日，可说两个好处、两个坏处，或一好一坏。</p></blockquote><h2 id="record-c2223-wkf-second" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-wkf-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-wkf-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>协作任务：</strong> 粤语</p><p><strong>选材料制作实用品</strong></p><p>五人一组，从八种物件中选两种，合作制作实用物品。学生记得饮管、纸巾盒、玻璃瓶、气球、光碟、报纸及塑料瓶，第八种未记清。自行讨论、制作并向老师汇报；一个版本老师全程不介入，完成后也没有即时评论。</p></blockquote><blockquote><p><strong>个人面谈：</strong> 英语</p><p><strong>自我介绍与择校</strong></p><p>小组任务后进行一对一面谈，自我介绍，说明希望入读王锦辉的原因，再根据回答追问。相近流程的一份反馈记全程约45分钟。</p></blockquote>',20)])])}const u=r(p,[["render",n]]);export{h as __pageData,u as default};
